def first_Missing_Positive(nums, n):
    # Initialize the index to 0
    i = 0
    # Iterate through the array
    while i < n:
        # If the current element is not at its correct position (i + 1)
        if nums[i] != i + 1:
            # Swap the elements to their correct positions
            nums[i], nums[nums[i] - 1] = nums[nums[i] - 1], nums[i]
        else:
            # Move to the next element
            i += 1
    # Iterate through the array again to find the first missing positive number
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    # If no missing positive number is found, return n + 1
    return n + 1
