def max_sum(triangle, n):
    # Initialize the first row of the triangle with the elements of the first row of the input triangle
    for i in range(n):
        triangle[i][0] = triangle[i][0]

    # Fill the triangle from the second row to the last row
    for i in range(1, n):
        for j in range(i + 1, n):
            triangle[i][j] = max(triangle[i - 1][j], triangle[i - 1][j - 1]) + triangle[i][j]

    # Return the maximum value in the last row of the triangle
    return max(triangle[n - 1])
