def newman_prime(n):
    """
    Find the nth Newman–Shanks–Williams prime number.

    Parameters:
    n (int): The position of the prime number to find.

    Returns:
    int: The nth Newman–Shanks–Williams prime number.
    """
    def is_newman_shanks_williams_prime(num):
        """Check if a number is Newman–Shanks–Williams."""
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    count = 0
    num = 2
    while True:
        if is_newman_shanks_williams_prime(num):
            count += 1
            if count == n:
                return num
        num += 1
